export default async function conversationPanes(review) {
  await review.reducedMotion(true);
  await review.reloadWithFixture(`(() => {
    const f=window.__modelReview, cwd=f.snapshot.cwd;
    const a={...structuredClone(f.snapshot),sequence:10,sessionId:'same-id',sessionPath:cwd+'/a.jsonl',status:'idle',messages:[{id:'a-user',order:0,role:'user',text:'会话 A：字体与布局',status:'done'},{id:'a-answer',order:1,role:'assistant',text:'### 会话 A\\n正文清晰，中文与 English 显示自然。',status:'done'}],activities:[],runs:[],historyTotal:2};
    const b={...structuredClone(a),sequence:20,sessionPath:cwd+'/b.jsonl',messages:[{id:'b-user',order:0,role:'user',text:'会话 B：后台任务',status:'done'},{id:'b-answer',order:1,role:'assistant',text:'### 会话 B\\n这是另一个会话的内容。',status:'done'}]};
    Object.assign(f.snapshot,a);
    const state={a,b,activations:[],diagnostics:[],terminalWrites:[],pending:null}; window.__paneReview=state;
    const mock=(name,fn)=>window.piDesktop[name]=async(...args)=>{f.calls.push({name,args:structuredClone(args)}); return fn(...args);};
    mock('listSessions',()=>[a,b].map((s,i)=>({path:s.sessionPath,id:s.sessionId,name:'会话 '+(i?'B':'A'),firstMessage:s.messages[0].text,modified:new Date().toISOString(),messageCount:2})));
    mock('getResidentSessionSnapshot',scope=>[a,b].find(s=>s.cwd===scope.cwd&&s.sessionId===scope.sessionId&&s.sessionPath===scope.sessionPath)||null);
    mock('activateResidentSession',scope=>{state.activations.push(scope); const s=[a,b].find(s=>s.cwd===scope.cwd&&s.sessionId===scope.sessionId&&s.sessionPath===scope.sessionPath); if(!s)return false; Object.assign(f.snapshot,structuredClone(s)); f.emitAgent({type:'reset',cwd}); f.emitAgent({...structuredClone(s),type:'ready',resumeKind:'warm'}); f.emitAgent({type:'status',status:'idle'}); return true;});
    mock('recordUiDiagnostic',event=>state.diagnostics.push(event));
    mock('listWorkspaceEntries',()=>[]);
    mock('getWorkspaceTerminal',cwd=>({id:'fixture-terminal',cwd,shell:'Renderer fixture',running:true,output:'Renderer fixture terminal',sequence:1,truncated:false}));
    mock('writeWorkspaceTerminal',request=>state.terminalWrites.push(request));
    mock('resizeWorkspaceTerminal',()=>undefined);
    mock('acknowledgeWorkspaceTerminal',()=>undefined);
    window.piDesktop.onWorkspaceTerminalEvent=()=>()=>{};
  })()`);
  await review.viewport(1440,1000);
  await review.waitFor('document.querySelector(".pd-turn-answer")?.textContent.includes("会话 A")');
  await review.assert('document.querySelector(".pd-conversation-panes").getBoundingClientRect().width > 1100','Single conversation fills the available main area');
  await review.evaluate('window.__paneReview.editor=document.querySelector("textarea"); window.__paneReview.transcript=document.querySelector(".pd-transcript"); true');
  await review.fill('.pd-composer-shell textarea','A 中未发送的草稿');
  await review.clickText('.pd-pane-toolbar button','左右分屏');
  await review.assert('document.querySelectorAll(".pd-conversation-pane").length===2 && document.querySelector("textarea")===window.__paneReview.editor','Splitting preserves the editor DOM');
  await review.evaluate(`(() => { const e=document.querySelector('.pd-pane-session-picker'); const option=[...e.options].find(o=>o.text.includes('会话 B')); e.value=option.value; e.dispatchEvent(new Event('change',{bubbles:true})); })()`);
  await review.waitFor('document.querySelector(".pd-conversation-pane.is-active .pd-turn-answer")?.textContent.includes("会话 B")');
  await review.assert('window.__paneReview.activations.at(-1).sessionPath.endsWith("b.jsonl") && document.querySelector(".pd-pane-preview").textContent.includes("会话 A")','Same-id sessions route by full path, and A remains visible');
  await review.waitFor('window.__paneReview.diagnostics.some(e=>e.kind==="session-open"&&e.outcome==="success")');
  await review.clickText('.pd-conversation-pane:not(.is-active) .pd-pane-header button','继续');
  await review.waitFor('document.querySelector(".pd-conversation-pane.is-active .pd-turn-answer")?.textContent.includes("会话 A")');
  await review.waitFor('document.querySelector(".pd-composer-shell textarea")?.value==="A 中未发送的草稿"');
  await review.assert('document.querySelector("textarea")===window.__paneReview.editor','Activating another pane also preserves the editor instance');
  await review.screenshot('panes-horizontal');
  await review.clickText('.pd-pane-toolbar button','上下分屏');
  await review.assert('document.querySelectorAll(".pd-conversation-pane").length===3','Nested vertical split creates a third pane');
  await review.evaluate('document.querySelector(".pd-pane-divider").focus()');
  await review.key('ArrowRight');
  await review.assert('document.querySelector(".pd-pane-divider").getAttribute("aria-valuenow")==="55"','Divider keyboard resizing updates the ratio');
  await review.screenshot('panes-nested');
  await review.clickText('.pd-pane-toolbar button','单窗格');
  await review.assert('document.querySelector("textarea")===window.__paneReview.editor && document.querySelectorAll(".pd-conversation-pane").length===1','Collapsing layout keeps pending input and editor identity');
  await review.record('font-rendering', `(() => { const s=getComputedStyle(document.querySelector('.pd-turn-answer .pd-markdown'));return {family:s.fontFamily,weight:s.fontWeight,size:s.fontSize,color:s.color}; })()`);
  await review.record('session-open-diagnostics','window.__paneReview.diagnostics');
  await review.screenshot('typography-final');
  await review.key('`',{ctrl:true});
  await review.waitFor('document.querySelector(".pd-workbench.is-open [data-segment-key=terminal]")?.getAttribute("aria-current")==="page"');
  await review.evaluate('document.querySelector(".pd-workbench .xterm-helper-textarea").focus()');
  await review.assert('document.activeElement?.classList.contains("xterm-helper-textarea")','The terminal owns keyboard focus before toggling it closed');
  await review.key('`',{ctrl:true});
  await review.waitFor('!document.querySelector(".pd-workbench.is-open")');
  await review.assert('window.__paneReview.terminalWrites.length===0','The terminal shortcut is consumed before xterm can send it to the shell');
  await review.evaluate('document.querySelector(".pd-settings-entry").focus()');
  await review.key('`',{ctrl:true});
  await review.waitFor('Boolean(document.querySelector(".pd-workbench.is-open"))');
  await review.click('.pd-workbench [data-segment-key="files"]');
  await review.key('`',{ctrl:true});
  await review.waitFor('document.querySelector(".pd-workbench [data-segment-key=terminal]")?.getAttribute("aria-current")==="page"');
  await review.assert('document.querySelector(".pd-terminal-pane").hidden===false','The shortcut switches a focused workbench from Files to Terminal');
  await review.key('`',{ctrl:true});
  await review.waitFor('!document.querySelector(".pd-workbench.is-open")');
  await review.click('.pd-settings-entry');
  await review.waitFor('Boolean(document.querySelector(".pd-settings-dialog"))');
  await review.key('`',{ctrl:true});
  await review.assert('!document.querySelector(".pd-workbench.is-open") && Boolean(document.querySelector(".pd-settings-dialog"))','Settings remains modal and blocks the terminal shortcut');
  await review.key('Escape');
  await review.waitFor('!document.querySelector(".pd-settings-dialog")');
  await review.evaluate(`(() => { const d=document.createElement('dialog'); d.id='shortcut-approval-modal'; d.setAttribute('role','alertdialog'); d.setAttribute('aria-modal','true'); d.innerHTML='<button>Approval fixture</button>'; document.body.append(d); d.showModal(); })()`);
  await review.key('`',{ctrl:true});
  await review.assert('document.querySelector("#shortcut-approval-modal").open && !document.querySelector(".pd-workbench.is-open")','A modal approval blocks the terminal shortcut');
  await review.evaluate('document.querySelector("#shortcut-approval-modal").close(); document.querySelector("#shortcut-approval-modal").remove()');
  await review.viewport(900,900);
  await review.key('`',{ctrl:true});
  await review.waitFor('document.querySelector(".pd-workbench.is-open")?.getAttribute("aria-modal")==="true"');
  await review.evaluate('document.querySelector(".pd-workbench .xterm-helper-textarea").focus()');
  await review.key('`',{ctrl:true});
  await review.waitFor('!document.querySelector(".pd-workbench.is-open")');
  await review.assert('window.__paneReview.terminalWrites.length===0','The shortcut also closes the focused terminal in narrow modal mode without writing shell input');
  await review.assert('document.documentElement.scrollWidth<=innerWidth','Narrow window has no horizontal page overflow');
  await review.screenshot('typography-narrow');
}
